/**
 * Refresh a Hero's Ancestry and Class items from their compendium source,
 * keeping training, spell and perk selections.
 * Select a hero token (or set a default character) and run.
 */
const SYS = "vagabond-app";
const actor = canvas.tokens.controlled[0]?.actor ?? game.user.character;

if (!actor || actor.type !== "hero") {
  return ui.notifications.warn("Select a hero token (or set a default character) first.");
}

const recordedUuid = (item) => item.getFlag("core", "sourceId") ?? item._stats?.compendiumSource ?? null;

const findSource = async (item) => {
  const uuid = recordedUuid(item);

  if (uuid) {
    try {
      const doc = await fromUuid(uuid);
      if (doc && doc.documentName === "Item" && doc.type === item.type && doc !== item) {
        return { doc, how: "compendium source" };
      }
    } catch (e) { /* ignore */ }
  }

  for (const pack of game.packs.filter(p => p.documentName === "Item" && p.metadata.packageName === SYS)) {
    const index = await pack.getIndex({ fields: ["type"] });
    const entry = index.find(e => e.type === item.type && e.name === item.name);
    if (entry) return { doc: await pack.getDocument(entry._id), how: `compendium ${pack.collection}` };
  }

  const worldDoc = game.items.find(i => i.type === item.type && i.name === item.name);

  return worldDoc 
    ? { doc: worldDoc, how: "world item source" } 
    : null;
};

const sameRule = (a, b) =>
  a.id === b.id || (a.key === b.key && a.label && a.label === b.label);

// Rules added to the hero's copy (e.g. the "Elective Trainings" rule) not defined on the source Item.
const isHeroAddedRule = (rule) =>
  rule.key === "ChoiceSet" && rule.channel === "path" &&
  (rule.label === "Elective Trainings" ||
   (rule.choices ?? []).some(c => (typeof c === "string" ? c : c?.value ?? "").includes("skills."))
  );

const items = actor.items.filter(i => ["ancestry", "class"].includes(i.type));
if (items.length === 0) return ui.notifications.warn(`${actor.name} has no ancestry or class item.`);

const report = [];

for (const item of items) {
  const found = await findSource(item);
  if (!found) {
    report.push(`<li><b>${item.name}</b> (${item.type}): no source found, skipped.</li>`);
    continue;
  }
  const { doc: source, how } = found;

  const oldRules = foundry.utils.deepClone(item.system.rules ?? []);
  const oldSelections = foundry.utils.deepClone(item.getFlag(SYS, "ruleSelections") ?? {});
  const newSystem = foundry.utils.deepClone(source.system.toObject());
  newSystem.rules ??= [];

  const merged = foundry.utils.deepClone(oldSelections);

  for (const rule of newSystem.rules) {
    const oldRule = oldRules.find(r => sameRule(r, rule));
    if (!oldRule) continue;
    if (oldRule.id !== rule.id && oldSelections[oldRule.id]?.length) {
      merged[rule.id] = oldSelections[oldRule.id];
    }
    if (Array.isArray(oldRule.selections) && oldRule.selections.length && !merged[rule.id]?.length) {
      rule.selections = foundry.utils.deepClone(oldRule.selections);
    }
  }

  // Keep player-selected training rules.
  for (const oldRule of oldRules) {
    if (newSystem.rules.some(r => sameRule(r, oldRule))) continue;
    if (!isHeroAddedRule(oldRule)) continue;
    newSystem.rules.push(foundry.utils.deepClone(oldRule));
  }

  await item.update({ name: source.name, img: source.img, system: newSystem }, { diff: false });
  await item.setFlag(SYS, "ruleSelections", merged);
  await item.setFlag("core", "sourceId", source.uuid);

  report.push(`<li><b>${source.name}</b> (${item.type}): Successfully refreshed from ${how}.</li>`);
}

await actor.system?.forceUpdate?.();
actor.prepareData();
actor.sheet?.render(false);

ChatMessage.create({
  speaker: ChatMessage.getSpeaker({ actor }),
  whisper: [game.user.id],
  content: `<p><b>${actor.name}</b> refreshed from compendium:</p><ul>${report.join("")}</ul>`
});
